import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.BmD0ICqc.js";const c="/study/images/browser/storage-map.svg",s="/study/images/browser/storage-transaction-lifetime.svg",f=JSON.parse('{"title":"ブラウザの保存領域 — localStorage・IndexedDB・Cache APIとデータの寿命","description":"","frontmatter":{"title":"ブラウザの保存領域 — localStorage・IndexedDB・Cache APIとデータの寿命","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"localStorage、IndexedDB、Cache APIのデータ形式と完了の意味を整理する。origin・partition、トランザクションの寿命、容量制限、永続化の許可と削除条件を分けて説明する。","aliases":["ブラウザストレージ","Web Storage","localStorage","sessionStorage","IndexedDB","object store","IDBTransaction","Cache API","CacheStorage","storage event","quota","StorageManager","persist","eviction","storage partitioning"],"verification":"一次資料照合（2026-11-05）"}},"headers":[],"relativePath":"browser/storage-lifetime.md","filePath":"browser/storage-lifetime.md"}'),n={name:"browser/storage-lifetime.md"};function i(d,e,l,h,p,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ブラウザの保存領域-—-localstorage・indexeddb・cache-apiとデータの寿命" tabindex="-1">ブラウザの保存領域 — localStorage・IndexedDB・Cache APIとデータの寿命 <a class="header-anchor" href="#ブラウザの保存領域-—-localstorage・indexeddb・cache-apiとデータの寿命" aria-label="Permalink to &quot;ブラウザの保存領域 — localStorage・IndexedDB・Cache APIとデータの寿命&quot;">​</a></h1><p>ページを再読み込みすると、JavaScriptの変数は通常作り直されます。ブラウザの保存APIを使うと、設定やレコード、取得済みの応答などを、ページの実行が終わったあとも残せます。</p><p>読むときは、<strong>保存する値の形式、操作の完了、データが残る条件</strong>を分けます。「保存成功」と「ブラウザを閉じても必ず永久に残る」は同じ意味ではありません。</p><h2 id="三つのapiは、保存するものと操作単位が違う" tabindex="-1">三つのAPIは、保存するものと操作単位が違う <a class="header-anchor" href="#三つのapiは、保存するものと操作単位が違う" aria-label="Permalink to &quot;三つのAPIは、保存するものと操作単位が違う&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>主に扱うもの</th><th>操作と用途の例</th></tr></thead><tbody><tr><td><code>localStorage</code></td><td>キーと値の文字列</td><td>同期API。表示設定などの小さな値</td></tr><tr><td><code>IndexedDB</code></td><td>キー付きの構造化データ</td><td>非同期API。複数レコードの検索・更新、トランザクション</td></tr><tr><td><code>Cache API</code></td><td><code>Request</code>と<code>Response</code>の組</td><td>Promiseを使う非同期API。アプリが管理する応答の保存と再利用</td></tr></tbody></table><p>この表は選択の目安です。IndexedDBに設定を保存してもよく、Cache APIに自作Responseを保存することもできます。非同期APIでも、値の準備・変換やコールバックの計算が自動的に別スレッドへ移るわけではありません。<a href="/study/browser/event-loop-promises.html">イベントループとasync/await</a>も参照してください。</p><h2 id="originとpartition-—-同じサイトに見えても保存先が違う" tabindex="-1">originとpartition — 同じサイトに見えても保存先が違う <a class="header-anchor" href="#originとpartition-—-同じサイトに見えても保存先が違う" aria-label="Permalink to &quot;originとpartition — 同じサイトに見えても保存先が違う&quot;">​</a></h2><p><strong>origin</strong>は、HTTP(S)では基本的にscheme・host・portの組です。<code>https://example.com</code>と<code>http://example.com</code>、同じhostの別portは異なります。一方、<code>/study/</code>と<code>/game/</code>というpathの違いだけでは保存領域を分けません。同じ保存領域を使うアプリ同士は、キー・DB名・Cache名を区別する必要があります。これらの名前やキーのprefixは、同じoriginで動く別のscriptからのアクセスを隔離する境界ではありません。<a href="https://storage.spec.whatwg.org/#storage-keys" target="_blank" rel="noreferrer">WHATWG Storage: Storage keys</a></p><p>さらにブラウザには、第三者iframeなどの保存領域を、埋め込み先のtop-level siteも使って分割する<strong>partitioning</strong>があります。たとえばFirefoxのState Partitioningは、リソースのoriginとtop-level siteを組み合わせます。同じoriginでも、別サイトに埋め込まれた場合に同じデータを読めるとは限りません。具体的な分割やアクセス制限はブラウザの方針に依存します。<a href="https://developer.mozilla.org/en-US/docs/Web/Privacy/Guides/State_Partitioning#state_partitioning" target="_blank" rel="noreferrer">Mozilla: State Partitioning</a></p><p>保存先はブラウザのプロファイルや通常・プライベートの利用環境でも分かれます。別端末への同期やサーバーへの送信が、この三つのAPIだけで自動的に行われるわけでもありません。</p><figure><img src="'+c+'" alt="ブラウザの保存領域をlocalStorageの文字列、IndexedDBのレコードとトランザクション、Cache APIのRequestとResponseに分け、originやpartition、容量と削除方針が関係することを示す図" width="760" height="1510" loading="lazy"><figcaption>保存形式と操作単位を選んだ後も、容量・保存許可・削除条件は別に扱います。三つのAPIをまとめて更新する共通トランザクションはありません。<a href="/study/images/browser/storage-map.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="localstorage-—-同期的な文字列の読み書き" tabindex="-1">localStorage — 同期的な文字列の読み書き <a class="header-anchor" href="#localstorage-—-同期的な文字列の読み書き" aria-label="Permalink to &quot;localStorage — 同期的な文字列の読み書き&quot;">​</a></h2><p><code>localStorage.setItem(key, value)</code>は値を文字列として保存し、<code>getItem(key)</code>は文字列、存在しないキーなら<code>null</code>を返します。キーと値はUTF-16の文字列として扱います。これはAPI上の文字列表現であり、ディスク上の物理配置が常に「一文字2byte」になるという説明ではありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/localStorage#description" target="_blank" rel="noreferrer">MDN: localStorage</a></p><p>オブジェクトを保存するなら、たとえば<code>JSON.stringify(record)</code>でJSON文字列へ変換し、読み出して<code>JSON.parse(text)</code>します。JSONは任意のJavaScriptオブジェクトを、その型・参照関係までそのまま保存する形式ではありません。読み出した内容の形式やバージョンも、アプリ側で確かめます。</p><p>Web Storageは<strong>同期API</strong>です。呼び出し中は、そのJavaScript実行を先へ進められません。大量の文字列化と保存を頻繁に行うと、画面操作や描画の機会に影響します。<code>await localStorage.setItem(...)</code>と書いても、同期処理を非同期I/Oへ変えることにはなりません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Web_Storage_API#concepts_and_usage" target="_blank" rel="noreferrer">MDN: Web Storageの同期動作</a></p><p>保存APIは失敗もします。保存領域へのアクセスがポリシーなどで許されない場合の<code>SecurityError</code>や、書き込みできない場合の<code>QuotaExceededError</code>などを処理します。<code>localStorage</code>プロパティの取得自体が例外になる場合もあるため、保存呼び出しだけを囲めば十分とは限りません。<a href="https://html.spec.whatwg.org/multipage/webstorage.html#dom-localstorage" target="_blank" rel="noreferrer">WHATWG HTML: localStorage</a></p><h3 id="同期呼び出しでも、読み出し・計算・書き戻しは一括でない" tabindex="-1">同期呼び出しでも、読み出し・計算・書き戻しは一括でない <a class="header-anchor" href="#同期呼び出しでも、読み出し・計算・書き戻しは一括でない" aria-label="Permalink to &quot;同期呼び出しでも、読み出し・計算・書き戻しは一括でない&quot;">​</a></h3><p>二つのタブが同じカウンタを読み、どちらも<code>10</code>を得てから<code>11</code>を書けば、一回分の更新が失われ得ます。個々の<code>getItem</code>と<code>setItem</code>が同期でも、その間を含むread–modify–write全体のロックにはなりません。HTML仕様も、共有状態にはロック機構がないと考えるよう説明しています。<a href="https://html.spec.whatwg.org/multipage/webstorage.html#webstorage" target="_blank" rel="noreferrer">WHATWG HTML: Web Storage</a></p><p><strong>storageイベント</strong>は、共有する保存領域を別のdocumentが変更したことを知らせます。変更を行ったwindow自身には発火しません。通知を受けて表示を更新できますが、複数操作を原子的にする仕組みではありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/storage_event" target="_blank" rel="noreferrer">MDN: storage event</a></p><p><code>sessionStorage</code>も同期の文字列保存ですが、originに加えてタブなどのtop-level browsing contextに結び付くページセッションが基本単位です。同じタブの再読み込みでは保持されます。localStorageと同じ長期保存先として扱いません。Cookieが条件に合うHTTP要求へ送られる仕組みは、<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>で扱います。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Window/sessionStorage" target="_blank" rel="noreferrer">MDN: sessionStorage</a></p><h2 id="indexeddb-—-レコードとトランザクション" tabindex="-1">IndexedDB — レコードとトランザクション <a class="header-anchor" href="#indexeddb-—-レコードとトランザクション" aria-label="Permalink to &quot;IndexedDB — レコードとトランザクション&quot;">​</a></h2><p>IndexedDBは、<strong>object store</strong>というレコードの集まりに、キーと値を保存します。<strong>index</strong>は、レコード内の指定した値から検索するための索引です。SQLの文字列を渡すAPIではありません。値は保存用のstructured cloneで直列化され、配列・オブジェクト・バイナリなどを扱えますが、関数やDOMノードなどは保存できません。元のJSオブジェクトと同一の参照を永続化するわけでもありません。<a href="https://w3c.github.io/IndexedDB/#object-store-concept" target="_blank" rel="noreferrer">IndexedDB: Object storesとvalues</a></p><p><strong>トランザクション</strong>は、一つのDB内の、指定したobject store群に対する操作をまとめます。<code>readonly</code>は読み取り、<code>readwrite</code>は更新を許すモードです。同じトランザクションの変更は、全体をcommitするか、abortで取り消します。複数レコードの整合した更新には、関連する処理を一つの適切なトランザクションへ入れます。<a href="https://w3c.github.io/IndexedDB/#transaction-concept" target="_blank" rel="noreferrer">IndexedDB: Transactions</a></p><h3 id="requestのsuccessとtransactionのcompleteは違う" tabindex="-1">requestのsuccessとtransactionのcompleteは違う <a class="header-anchor" href="#requestのsuccessとtransactionのcompleteは違う" aria-label="Permalink to &quot;requestのsuccessとtransactionのcompleteは違う&quot;">​</a></h3><p><code>store.put(...)</code>などが返す<code>IDBRequest</code>の<code>success</code>は、その要求の成功です。その後、同じトランザクションの別要求が失敗し、全体がabortすることもあります。<strong>更新全体の成功はtransactionのcompleteで確認します。</strong> 要求成功時に「保存完了」と表示すると、取り消された更新を完了扱いしかねません。<a href="https://w3c.github.io/IndexedDB/#transaction-lifecycle" target="_blank" rel="noreferrer">IndexedDB: Transaction lifecycle</a></p><p><code>IDBRequest</code>は、そのままではPromiseではありません。単に<code>await store.put(...)</code>と書いても、要求やトランザクションの完了を待つコードにはなりません。Promiseで包む場合も、要求の結果を待つ処理と、transactionの<code>complete</code>・<code>abort</code>を回収する処理を区別します。</p><h3 id="transactionは、外部の非同期処理を待つ箱ではない" tabindex="-1">transactionは、外部の非同期処理を待つ箱ではない <a class="header-anchor" href="#transactionは、外部の非同期処理を待つ箱ではない" aria-label="Permalink to &quot;transactionは、外部の非同期処理を待つ箱ではない&quot;">​</a></h3><p>transactionは、作成時や関連する要求イベントの処理中などの<strong>active</strong>期間に新しい要求を受け付けます。制御が戻るとinactiveになり、保留中の要求がなくなると自動commitへ進み得ます。作成後に無関係な<code>fetch</code>やtimerを<code>await</code>し、戻ってから要求を追加しようとしても、すでに使えない場合があります。「すべてのawaitで必ず無効になる」という規則ではなく、transactionのactive期間と自動commitが関係します。<a href="https://w3c.github.io/IndexedDB/#transaction-lifecycle" target="_blank" rel="noreferrer">IndexedDB: Transaction lifecycle</a></p><p>外部データの取得などは先に済ませ、必要なDB要求を有効な期間に登録します。transactionを長時間開いたまま通信や利用者の入力を待たせる設計は避けます。</p><p>DBの構造変更は、バージョンを上げて開く際の<code>upgradeneeded</code>で行います。古い接続が別タブに残っていると、更新を求める側に<code>blocked</code>が起こり得ます。既存接続は<code>versionchange</code>を扱い、必要な処理をしたうえで<code>db.close()</code>し、再読み込みなどへつなぎます。DBの削除も、残った接続に妨げられる場合があります。<a href="https://w3c.github.io/IndexedDB/#upgrade-transaction" target="_blank" rel="noreferrer">IndexedDB: Upgrade transactions</a></p><figure><img src="'+s+'" alt="IndexedDBの個別request成功とtransaction完了を分け、active期間に要求を登録すること、保存成功後にも容量や利用者による削除が関係することを示す図" width="760" height="1510" loading="lazy"><figcaption>requestの成功通知は途中経過です。transactionの完了を確認しても、他の保存APIまで同時にcommitされたり、データが永久に残ったりする保証にはなりません。<a href="/study/images/browser/storage-transaction-lifetime.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="cache-api-—-httpキャッシュとは別の応答保存" tabindex="-1">Cache API — HTTPキャッシュとは別の応答保存 <a class="header-anchor" href="#cache-api-—-httpキャッシュとは別の応答保存" aria-label="Permalink to &quot;Cache API — HTTPキャッシュとは別の応答保存&quot;">​</a></h2><p><code>caches.open(name)</code>で名前付きCacheを開き、<code>cache.put(request, response)</code>でRequestとResponseの組を保存します。照合にはURLや、Responseの<code>Vary</code>などが関係します。通常のページのWindowからも利用でき、<strong>Service Workerの登録は必須ではありません。</strong> Cache APIはsecure context向けで、たとえばHTTPSや、信頼できるローカル開発用のHTTP loopback環境で利用します。<a href="https://w3c.github.io/ServiceWorker/#cache-interface" target="_blank" rel="noreferrer">Service Workers: Cache API</a>、<a href="https://w3c.github.io/webappsec-secure-contexts/#is-origin-trustworthy" target="_blank" rel="noreferrer">Secure Contexts: Potentially trustworthy origins</a></p><p><a href="/study/network/http-caching.html">HTTPキャッシュ</a>は、HTTPの鮮度や再検証の規則に従う保存です。一方、Cache APIは<code>Cache-Control</code>などのHTTPキャッシュ指示に従って自動的に保存可否や期限を管理する仕組みではありません。<code>max-age</code>の経過だけで自動更新・削除されるとは考えず、バージョンや更新・削除をアプリが管理します。ただし、ブラウザの保存領域の削除方針から独立して永久に残るわけではありません。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Cache" target="_blank" rel="noreferrer">MDN: Cache</a>、<a href="https://w3c.github.io/ServiceWorker/#cache-lifetimes" target="_blank" rel="noreferrer">Service Workers: Cache lifetimes</a></p><p><code>cache.add(url)</code>は取得と保存をまとめ、取得した成功応答などを保存します。<code>put</code>は、すでに持つResponseを渡す操作です。<code>new Response(...)</code>で作った固定データの保存なら、<code>put</code>だけで外部取得は起きません。<code>put</code>にも、GETのHTTP(S)要求であることなどの制約があります。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Cache/add" target="_blank" rel="noreferrer">MDN: Cache.add</a>、<a href="https://w3c.github.io/ServiceWorker/#cache-put" target="_blank" rel="noreferrer">Service Workers: Cache.put</a></p><p>Responseの本文は消費するStreamです。保存と画面用の読み出しの両方に使うなら、本文を消費する前に<code>response.clone()</code>で分け、片方を<code>put</code>へ渡します。消費後にcloneして読み直せるわけではありません。<code>cache.match()</code>から得たResponseにも同様の本文の寿命があります。<a href="https://fetch.spec.whatwg.org/#dom-response-clone" target="_blank" rel="noreferrer">Fetch: Response.clone</a></p><h2 id="容量・永続化の許可・削除は別の条件" tabindex="-1">容量・永続化の許可・削除は別の条件 <a class="header-anchor" href="#容量・永続化の許可・削除は別の条件" aria-label="Permalink to &quot;容量・永続化の許可・削除は別の条件&quot;">​</a></h2><p><strong>quota</strong>はブラウザが認める保存量の制限です。固定の容量を全ブラウザ共通の契約とは考えません。<code>navigator.storage.estimate()</code>の<code>usage</code>と<code>quota</code>は概算で、物理ディスクの空き容量そのものではありません。書き込み用の容量予約にもならず、推定上の余裕があっても、その後の保存が失敗する場合があります。<a href="https://storage.spec.whatwg.org/#usage-and-quota" target="_blank" rel="noreferrer">WHATWG Storage: Usage and quota</a></p><p>通常の<strong>best-effort</strong>保存は、保存圧迫などでブラウザがデータを削除するevictionの対象になり得ます。<code>navigator.storage.persist()</code>はpersistent storageの許可を求め、許可されたかをbooleanで返します。許可された保存領域を自動的な圧迫削除から保護するための仕組みで、バックアップや別端末への複製ではありません。利用者によるサイトデータ削除などを防ぐものでもありません。<a href="https://storage.spec.whatwg.org/#persistence" target="_blank" rel="noreferrer">WHATWG Storage: Persistence permission</a></p><p>プライベートブラウジングでは容量や寿命が異なり、その利用環境の終了時にデータが削除されるのが一般的です。削除条件・許可・ブラウザの対応を含め、アプリは保存領域が空の状態からも扱えるようにします。<a href="https://developer.mozilla.org/en-US/docs/Web/API/Storage_API/Storage_quotas_and_eviction_criteria" target="_blank" rel="noreferrer">MDN: Storage quotas and eviction criteria</a></p><h3 id="apiの成功は、永久保存や厳密なfsyncの証明ではない" tabindex="-1">APIの成功は、永久保存や厳密なfsyncの証明ではない <a class="header-anchor" href="#apiの成功は、永久保存や厳密なfsyncの証明ではない" aria-label="Permalink to &quot;APIの成功は、永久保存や厳密なfsyncの証明ではない&quot;">​</a></h3><p>APIが成功した段階と、電源断にも耐える形で記憶媒体へ反映された段階を同一視しません。IndexedDBにも<code>strict</code>・<code>relaxed</code>・<code>default</code>のdurability hintがあり、commit時に耐久性と性能をどう扱うかが異なります。すべてのtransactionの<code>complete</code>を「厳密なfsync済み」と説明するのは不正確です。耐久性が高い設定でも、後日の利用者の削除とは別です。<a href="https://w3c.github.io/IndexedDB/#transaction-concept" target="_blank" rel="noreferrer">IndexedDB: Transaction durability</a></p><p>また、localStorageへの設定保存、IndexedDBへのレコード保存、Cache APIへの応答保存は、共通の一括トランザクションではありません。順に呼び出して二つ目が失敗しても、一つ目が自動的に戻ることはありません。三方式へ分けるなら、途中失敗した状態や、データのバージョンが異なる状態も扱います。</p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p><a href="/study/practice/browser/storage-observation.html">保存・読出し・再読み込み後の確認</a>では、教材専用のキー・DB・Cacheに固定の小さなデータを保存し、それぞれの方法で読み出します。削除も教材が所有するデータに限定します。Cache APIには自作Responseを保存するため、外部fetchは必要ありません。</p><p>再読み込み後に同じ値を読めたことは、その環境・その時点での保持を確認した結果です。ブラウザの強制終了・電源断・容量圧迫への耐久性や、全ブラウザで同じ削除方針になることまで、この観察で確認したとは扱いません。</p><p>ページからの要求に保存済みResponseを返す方法は、<a href="/study/browser/service-worker-offline.html">Service Workerとオフライン動作</a>で扱います。</p>',47)])])}const u=t(n,[["render",i]]);export{f as __pageData,u as default};
